/** calcTotal: sum of price × quantity over the cart, less 10% when the cart holds 10 or more units. shippingFee: shipping for the cart, in dollars. */
export function calcTotal(items: Item[]): number {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const units = items.reduce((sum, item) => sum + item.qty, 0);
  return units >= 10 ? subtotal * 0.9 : subtotal;
}

