import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal } from "../src/pricing.ts";

test("cart under 10 units pays the plain subtotal", () => {
  assert.equal(calcTotal([{ sku: "apple", price: 3, qty: 4 }, { sku: "pear", price: 5, qty: 2 }]), 22);
  assert.equal(calcTotal([{ sku: "apple", price: 2, qty: 9 }]), 18);
});

test("cart of 10 or more units gets 10% off", () => {
  assert.equal(calcTotal([{ sku: "apple", price: 3, qty: 10 }]), 27);
  assert.equal(calcTotal([{ sku: "apple", price: 2, qty: 6 }, { sku: "pear", price: 1, qty: 5 }]), 15.3);
});

test("the discount threshold counts units across the whole cart, not lines", () => {
  assert.equal(calcTotal([{ sku: "apple", price: 1, qty: 5 }, { sku: "pear", price: 2, qty: 5 }]), 13.5);
});

